def build(g):
    head, header, cta, footer, vid, faq_html, faq_schema = g["head"], g["header"], g["cta"], g["footer"], g["vid"], g["faq_html"], g["faq_schema"]
    I_ARROW, I_PHONE, TEL, PHONE, OUT, SERVICES = g["I_ARROW"], g["I_PHONE"], g["TEL"], g["PHONE"], g["OUT"], g["SERVICES"]
    for pg in PAGES:
        kind, name, alt = pg["media"]
        if kind == "vid":
            m = f'<img src="media/{name}.webp" alt="" width="540" height="720" fetchpriority="high" style="position:absolute;inset:0"><video muted loop playsinline preload="none" poster="media/{name}.webp" data-src="media/{name}.mp4" aria-label="{alt}" style="position:relative"></video>'
        else:
            m = f'<img src="media/{name}.webp" alt="{alt}" width="825" height="1100" fetchpriority="high">'
        intro = "".join(f"<p>{p}</p>" for p in pg["intro"])
        incl = "".join(f'<li data-reveal data-delay="{i*60}"><h3>{t}</h3><p>{d}</p></li>' for i,(t,d) in enumerate(pg["incl"]))
        steps = "".join(f'<li data-reveal data-delay="{i*80}"><h3>{t}</h3><p>{d}</p></li>' for i,(t,d) in enumerate(pg["steps"]))
        gal = ""
        for k, n, a in pg["gal"]:
            inner = vid(n, a) if k == "vid" else f'<img src="media/{n}.webp" alt="{a}" loading="lazy" width="825" height="1100">'
            gal += f'<figure data-reveal>{inner}<figcaption>{a}</figcaption></figure>'
        others = "".join(f'<li><a href="{h}">{n}</a></li>' for h, n in SERVICES if h != pg["file"])
        bc = {"@context":"https://schema.org","@type":"BreadcrumbList","itemListElement":[{"@type":"ListItem","position":1,"name":"Home","item":"index.html"},{"@type":"ListItem","position":2,"name":pg["crumb"],"item":pg["file"]}]}
        svc = {"@context":"https://schema.org","@type":"Service","serviceType":pg["crumb"],"provider":{"@type":"GeneralContractor","name":"Multilease Excavation Pty Ltd","telephone":"+61 448 741 813"},"areaServed":{"@type":"City","name":"Sydney"},"description":pg["desc"]}
        anchor = f' id="{pg["anchor_id"]}"' if pg["anchor_id"] else ""
        html = f'''{head(pg["title"], pg["desc"], [faq_schema(pg["faq"]), bc, svc], pg["file"])}{header(home=False)}
<main id="main">
<section class="page-hero" aria-labelledby="h1">
  <div class="hero-grid">
    <div>
      <p class="crumbs"><a href="index.html">Home</a> / {pg["crumb"]}</p>
      <h1 id="h1">{pg["h1"]}</h1>
      <p class="lede" style="color:#cfcabe">{pg["lede"]}</p>
      <div class="hero-ctas"><a class="btn btn-primary" href="#quote">Get my free quote {I_ARROW}</a><a class="btn btn-ghost" href="{TEL}">{I_PHONE}Call {PHONE}</a></div>
    </div>
    <div class="hero-media"><div class="vcard">{m}<span class="tag"><i></i>Multilease on site</span></div></div>
  </div>
</section>
<section class="sec"><div class="wrap prose" data-reveal><span class="label">Overview</span><h2>{pg["intro_h"]}</h2>{intro}</div></section>
<section class="sec" style="padding-top:0"{anchor}><div class="wrap"><div class="head" data-reveal><span class="label">What is included</span><h2>Types of {pg["crumb"].lower()} work <span class="soft">we take on.</span></h2></div><ul class="incl">{incl}</ul></div></section>
<section class="band sec"><div class="wrap"><div class="head" data-reveal><span class="label">The process</span><h2>How it runs, <span class="soft">step by step.</span></h2></div><ol class="steps4" style="color:var(--ink)">{steps}</ol>
<div class="gal">{gal}</div></div></section>
<section class="sec"><div class="wrap split" style="margin-top:0">
  <div class="review" data-reveal><div class="stars" aria-label="5 out of 5">&#9733;&#9733;&#9733;&#9733;&#9733;</div><blockquote>A Google review about this service goes here, with the customer's name and suburb.</blockquote><span class="ph-note">Placeholder on this concept site</span></div>
  <div class="area" data-reveal data-delay="100"><h3>Other services</h3><ul>{others}<li><a href="index.html#fleet">Our fleet</a></li></ul><p>Based in Regentville, working across Greater Sydney: Western Sydney, the Inner West, the North Shore and South West Sydney.</p></div>
</div></section>
<section class="sec" style="padding-top:0"><div class="wrap"><div class="head" data-reveal><span class="label">Questions</span><h2>{pg["crumb"]} <span class="soft">FAQs.</span></h2></div><div class="faq">{faq_html(pg["faq"])}</div></div></section>
{cta()}
</main>
{footer()}'''
        (OUT / pg["file"]).write_text(html)
